-- Express cargo v1 table design (PREVIEW ONLY, not a migration).
-- Real tables will be generated by Ash from resources. Matches docs/schema.md.
-- Self-contained: defines a stand-in for ash_money's money_with_currency type.

BEGIN;

CREATE EXTENSION IF NOT EXISTS citext;

DO $$ BEGIN
  CREATE TYPE money_with_currency AS (currency_code varchar, amount numeric);
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

CREATE TYPE user_role AS ENUM ('staff', 'supervisor', 'admin');
CREATE TYPE shipment_status AS ENUM ('received', 'in_transit', 'arrived', 'collected', 'cancelled');
CREATE TYPE incident_type AS ENUM ('return_to_sender', 'redirect', 'lost', 'damaged');

-- Reference data ---------------------------------------------------------
CREATE TABLE locations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL UNIQUE
);

CREATE TABLE stations (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  location_id uuid NOT NULL REFERENCES locations,
  name text NOT NULL,
  active boolean NOT NULL DEFAULT true,
  UNIQUE (location_id, name)
);

CREATE TABLE routes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  origin_location_id uuid NOT NULL REFERENCES locations,
  destination_location_id uuid NOT NULL REFERENCES locations,
  UNIQUE (origin_location_id, destination_location_id),
  CHECK (origin_location_id <> destination_location_id)
);

CREATE TABLE size_classes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL UNIQUE,
  active boolean NOT NULL DEFAULT true
);

CREATE TABLE sale_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  name text NOT NULL UNIQUE,
  unit_price money_with_currency NOT NULL,
  active boolean NOT NULL DEFAULT true
);

CREATE TABLE price_list_versions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  effective_from date NOT NULL UNIQUE
);

CREATE TABLE price_list_weight_rates (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  version_id uuid NOT NULL REFERENCES price_list_versions,
  route_id uuid NOT NULL REFERENCES routes,
  price_per_kg money_with_currency NOT NULL,
  UNIQUE (version_id, route_id)
);

CREATE TABLE price_list_size_rates (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  version_id uuid NOT NULL REFERENCES price_list_versions,
  route_id uuid NOT NULL REFERENCES routes,
  size_class_id uuid NOT NULL REFERENCES size_classes,
  price money_with_currency NOT NULL,
  UNIQUE (version_id, route_id, size_class_id)
);

CREATE TABLE station_settings (
  station_id uuid PRIMARY KEY REFERENCES stations,
  cancel_requires_approval boolean NOT NULL DEFAULT true,
  overdue_threshold_days integer NOT NULL CHECK (overdue_threshold_days > 0)
);

-- Users ------------------------------------------------------------------
CREATE TABLE users (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  email citext NOT NULL UNIQUE,
  hashed_password text NOT NULL,
  confirmed_at timestamptz,
  role user_role NOT NULL,
  station_id uuid REFERENCES stations,
  CHECK ((role = 'admin' AND station_id IS NULL) OR (role <> 'admin' AND station_id IS NOT NULL))
);

-- Shipments --------------------------------------------------------------
CREATE TABLE waybill_counters (
  day date PRIMARY KEY,
  last_seq integer NOT NULL
);

CREATE TABLE shipments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  waybill text NOT NULL UNIQUE,                 -- EX-YYYYMMDD-SEQ
  origin_station_id uuid NOT NULL REFERENCES stations,
  destination_station_id uuid NOT NULL REFERENCES stations,
  route_id uuid NOT NULL REFERENCES routes,
  price_list_version_id uuid NOT NULL REFERENCES price_list_versions,
  sender_name text NOT NULL,
  sender_phone text NOT NULL,
  receiver_name text NOT NULL,
  receiver_phone text NOT NULL,                 -- normalised digits + country code
  declared_value money_with_currency,
  collection_code_hash text NOT NULL,
  shipment_total money_with_currency NOT NULL,
  created_by uuid NOT NULL REFERENCES users,
  inserted_at timestamptz NOT NULL DEFAULT now(),
  CHECK (origin_station_id <> destination_station_id)
);
CREATE INDEX shipments_receiver_phone_idx ON shipments (receiver_phone);

CREATE TABLE parcels (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  shipment_id uuid NOT NULL REFERENCES shipments,
  weight_kg numeric(8,2) NOT NULL CHECK (weight_kg > 0),
  size_class_id uuid NOT NULL REFERENCES size_classes,
  length_cm numeric(8,1),
  width_cm numeric(8,1),
  height_cm numeric(8,1),
  chargeable_amount money_with_currency NOT NULL
);

CREATE TABLE shipment_sale_items (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  shipment_id uuid NOT NULL REFERENCES shipments,
  sale_item_id uuid NOT NULL REFERENCES sale_items,
  quantity integer NOT NULL CHECK (quantity > 0),
  unit_price money_with_currency NOT NULL       -- snapshot
);

-- Append-only ------------------------------------------------------------
CREATE TABLE payments (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  shipment_id uuid NOT NULL REFERENCES shipments,
  method text NOT NULL,
  payer text NOT NULL,
  amount money_with_currency NOT NULL,          -- negative = refund
  station_id uuid NOT NULL REFERENCES stations,
  created_by uuid NOT NULL REFERENCES users,
  inserted_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE status_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  shipment_id uuid NOT NULL REFERENCES shipments,
  status shipment_status NOT NULL,
  station_id uuid NOT NULL REFERENCES stations,
  created_by uuid NOT NULL REFERENCES users,
  reason text,
  collector_name text,
  collector_id_number text,
  inserted_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX status_events_shipment_idx ON status_events (shipment_id, inserted_at);

CREATE TABLE arrival_measurements (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  parcel_id uuid NOT NULL REFERENCES parcels,
  weight_kg numeric(8,2) NOT NULL CHECK (weight_kg > 0),
  size_class_id uuid NOT NULL REFERENCES size_classes,
  station_id uuid NOT NULL REFERENCES stations,
  created_by uuid NOT NULL REFERENCES users,
  inserted_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE notes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  shipment_id uuid NOT NULL REFERENCES shipments,
  station_id uuid NOT NULL REFERENCES stations,
  text text NOT NULL,
  created_by uuid NOT NULL REFERENCES users,
  inserted_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE station_setting_changes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  station_id uuid NOT NULL REFERENCES stations,
  field text NOT NULL,
  value text NOT NULL,                          -- value set by this change
  changed_by uuid NOT NULL REFERENCES users,
  inserted_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE user_assignment_changes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id uuid NOT NULL REFERENCES users,
  old_role user_role,
  new_role user_role NOT NULL,
  old_station_id uuid REFERENCES stations,
  new_station_id uuid REFERENCES stations,
  changed_by uuid NOT NULL REFERENCES users,
  inserted_at timestamptz NOT NULL DEFAULT now()
);

-- Resolvable -------------------------------------------------------------
CREATE TABLE incidents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  shipment_id uuid NOT NULL REFERENCES shipments,
  type incident_type NOT NULL,
  reason text NOT NULL,
  created_by uuid NOT NULL REFERENCES users,
  resolved_by uuid REFERENCES users,
  resolved_at timestamptz,
  inserted_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE fraud_flags (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  shipment_id uuid NOT NULL REFERENCES shipments,
  kind text NOT NULL,                           -- measurement_mismatch | repeat_after_cancel
  resolved_by uuid REFERENCES users,
  resolved_at timestamptz,
  inserted_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE cancellation_requests (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  shipment_id uuid NOT NULL REFERENCES shipments,
  requested_by uuid NOT NULL REFERENCES users,
  approved_by uuid REFERENCES users,
  decided_at timestamptz,
  inserted_at timestamptz NOT NULL DEFAULT now(),
  CHECK (approved_by IS NULL OR approved_by <> requested_by)
);

-- Append-only enforcement (ADR-0005) -------------------------------------
CREATE FUNCTION reject_change() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN RAISE EXCEPTION '% is append-only', TG_TABLE_NAME; END $$;

CREATE TRIGGER payments_append_only BEFORE UPDATE OR DELETE ON payments
  FOR EACH ROW EXECUTE FUNCTION reject_change();
CREATE TRIGGER status_events_append_only BEFORE UPDATE OR DELETE ON status_events
  FOR EACH ROW EXECUTE FUNCTION reject_change();
CREATE TRIGGER arrival_measurements_append_only BEFORE UPDATE OR DELETE ON arrival_measurements
  FOR EACH ROW EXECUTE FUNCTION reject_change();
CREATE TRIGGER notes_append_only BEFORE UPDATE OR DELETE ON notes
  FOR EACH ROW EXECUTE FUNCTION reject_change();
CREATE TRIGGER station_setting_changes_append_only BEFORE UPDATE OR DELETE ON station_setting_changes
  FOR EACH ROW EXECUTE FUNCTION reject_change();
CREATE TRIGGER user_assignment_changes_append_only BEFORE UPDATE OR DELETE ON user_assignment_changes
  FOR EACH ROW EXECUTE FUNCTION reject_change();

COMMIT;
